/* Авторская практика ЕГЭ по ядерной физике. */
(() => {
  const fmt = x => String(Number(x.toFixed(5))).replace('.', ',');
  const variants = [
    ['Число нейтронов','',n=>[
      `В учебной таблице для ядра указаны массовое число ${100+n} и зарядовое число 50. Сколько нейтронов содержит ядро?`,50+n,
      'Массовое число равно сумме чисел протонов и нейтронов.',
      `N = A − Z = ${100+n} − 50 = ${50+n}.`]],
    ['Состав изотопа','',n=>[
      `В ядре изотопа 20 протонов и ${20+n} нейтронов. Найди массовое число.`,40+n,
      'Массовое число равно числу нуклонов в ядре.',
      `A = Z + N = 20 + ${20+n} = ${40+n}.`]],
    ['Изменение ядра при α-распаде','',n=>[
      `В модели радиоактивного распада зарядовое число материнского ядра равно ${70+n}. Каково зарядовое число дочернего ядра после одного α-распада?`,68+n,
      'α-частица уносит два протона и два нейтрона.',
      `Зарядовое число уменьшается на 2: Z = ${70+n} − 2 = ${68+n}.`]],
    ['Изменение ядра при β⁻-распаде','',n=>[
      `В условном β⁻-распаде исходное ядро содержит ${35+n} нейтронов. Сколько нейтронов остаётся в дочернем ядре?`,34+n,
      'При β⁻-распаде один нейтрон превращается в протон, массовое число сохраняется.',
      `Число нейтронов уменьшается на единицу: N = ${35+n} − 1 = ${34+n}.`]],
    ['Оставшиеся ядра через три периода','10⁶ ядер',n=>[
      `В образце первоначально ${8*n}·10⁶ ядер одного радиоактивного изотопа. Найди ожидаемое число нераспавшихся ядер через три периода полураспада в единицах 10⁶ ядер.`,n,
      'За каждый период полураспада ожидаемое число оставшихся ядер уменьшается вдвое.',
      `После трёх периодов N = ${8*n}·10⁶/2³ = ${n}·10⁶ ядер.`]],
    ['Определение периода полураспада','ч',n=>[
      `За ${3*n} часов активность образца одного изотопа уменьшилась в 8 раз. Дочерние продукты вклада в измерение не дают. Найди период полураспада в часах.`,n,
      'Активность данного изотопа пропорциональна числу его нераспавшихся ядер.',
      `Так как 8 = 2³, прошло три периода. T = ${3*n}/3 = ${n} ч.`]],
    ['Активность после двух периодов','Бк',n=>[
      `Начальная активность одного радиоактивного изотопа равна ${48*n} Бк. Какой станет его активность в беккерелях через два периода полураспада?`,12*n,
      'Постоянная распада неизменна, поэтому активность убывает в той же пропорции, что и число ядер.',
      `A = A₀/2² = ${48*n}/4 = ${12*n} Бк.`]],
    ['Доля распавшихся ядер','%',n=>[
      `Период полураспада изотопа равен ${n} мин. Какой процент исходных ядер в среднем распадётся за ${(2+n%4)*n} мин?`,100*(1-2**(-(2+n%4))),
      `Отношение времени к периоду равно ${2+n%4}. Доля оставшихся равна 2 в степени −${2+n%4}.`,
      `Доля распавшихся равна (1 − 1/${2**(2+n%4)}) · 100% = ${fmt(100*(1-2**(-(2+n%4))))}%.`]],
    ['Энергия связи по дефекту массы','МэВ',n=>[
      `Для модельного ядра дефект массы составляет ${fmt(n/1000)} а. е. м. Найди энергию связи в МэВ. Используй 1 а. е. м. · c² = 931,5 МэВ.`,.9315*n,
      'Энергия связи равна Δmc². Умножь дефект массы в атомных единицах на 931,5.',
      `E = ${fmt(n/1000)} · 931,5 = ${fmt(.9315*n)} МэВ.`]],
    ['Удельная энергия связи','МэВ/нуклон',n=>[
      `В учебной модели массовое число ядра равно ${10+n}, а энергия связи — ${fmt((10+n)*(6+n/10))} МэВ. Найди энергию связи на один нуклон.`,6+n/10,
      'Удельная энергия связи равна полной энергии связи, делённой на число нуклонов.',
      `Eуд = ${fmt((10+n)*(6+n/10))}/${10+n} = ${fmt(6+n/10)} МэВ/нуклон.`]]
  ];

  for (const [index, [title, unit, build]] of variants.entries()) {
    for (let variant = 1; variant <= 20; variant++) {
      const [question, rawAnswer, plan, calculation] = build(variant + 1);
      const steps = [plan, calculation];
      const category = index >= 4 && index <= 7 ? 371 : 265;
      tasks.push({
        id: `ege-physics-nuclear-${index + 1}-${variant}`,
        grade: 11,
        domain: 'physics',
        subject: 'physics',
        exam: 'ege',
        topic: 0,
        topicName: 'Ядерная физика',
        examTopic: 'physics-ege-nuclear',
        level: index < 4 ? 0 : index < 8 ? 1 : 2,
        title, question, unit, steps,
        answer: Number(rawAnswer.toFixed(5)),
        hints: [plan],
        solution: steps.join(' '),
        review: {plan},
        source: {
          name: 'Решу ЕГЭ',
          id: 'Ядерная физика',
          type: 'тематический каталог',
          url: `https://phys-ege.sdamgia.ru/test?theme=${category}`,
          note: 'Авторская задача МатКлуба. По ссылке доступна дополнительная практика по теме.'
        }
      });
    }
  }
})();

